import { connection } from "next/server";
import { crmRoute } from "@/lib/pramaan/crm-data";
import { getContacts, updateContacts } from "@/lib/pramaan/contacts";
export async function GET(request: Request) {
  await connection();
  return crmRoute(request, scope => getContacts(scope));
}
export async function POST(request: Request) {
  return crmRoute(request, (scope, body) => updateContacts(scope, body));
}

"use client";
import { useEffect, useRef, useState, type FormEvent } from "react";
import { api, ApiError, useResource } from "@/lib/pramaan/client";
import type { Contact, ContactsData } from "@/lib/pramaan/contacts";
const field = "block w-full rounded border bg-background p-2";
const button = "rounded border px-3 py-2 hover:bg-muted disabled:opacity-50";

export function ContactsPanel() {
  const { data, error, loading, reload } = useResource<ContactsData>("/api/pramaan/contacts");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<string>();
  const [editing, setEditing] = useState<Contact | "person" | "company">();
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [conflict, setConflict] = useState(false);
  const [deleting, setDeleting] = useState<Contact>();
  const addPerson = useRef<HTMLButtonElement>(null);
  const addCompany = useRef<HTMLButtonElement>(null);
  const editButton = useRef<HTMLButtonElement>(null);
  const returnFocus = useRef<"person" | "company" | "edit" | undefined>(undefined);
  const contact = data?.contacts.find(c => c.id === selected);
  const draft = typeof editing === "object" ? editing : undefined;
  const kind = draft?.kind ?? (editing === "company" ? "company" : "person");
  useEffect(() => {
    if (!editing && returnFocus.current) {
      const target = returnFocus.current;
      (target === "edit" ? editButton.current : target === "person" ? addPerson.current : addCompany.current)?.focus();
      returnFocus.current = undefined;
    }
  }, [editing]);

  async function save(body: Record<string, unknown>, success = "Saved.") {
    if (busy || (draft?.id === body.id && body.action !== "save")) return false;
    setBusy(true); setMessage(""); setConflict(false);
    try {
      await api("/api/pramaan/contacts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      reload(); setMessage(success); return true;
    } catch (e) {
      setConflict(e instanceof ApiError && e.status === 409);
      setMessage(e instanceof Error ? e.message : "Something went wrong. Please try again.");
      return false;
    } finally { setBusy(false); }
  }
  function closeEditor() {
    returnFocus.current = draft ? "edit" : kind;
    setEditing(undefined);
  }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    if (await save({ action: "save", id: draft?.id, revision: draft?.revision, kind, name: form.get("name"), email: form.get("email"), companyId: form.get("companyId") ?? "" })) closeEditor();
  }
  if (loading && !data) return <p role="status">Loading contacts…</p>;
  if (error) return <div role="alert"><p>{error.message}</p><button className={button} onClick={reload}>Try again</button></div>;
  const companies = new Map(data?.contacts.filter(c => c.kind === "company").map(c => [c.id, c.name]));
  const matches = data?.contacts.filter(c => `${c.name} ${c.email} ${companies.get(c.companyId) ?? ""}`.toLowerCase().includes(search.toLowerCase())) ?? [];
  return <div className="space-y-6">
    <label className="block">Search people and companies<input className={field} value={search} onChange={e => setSearch(e.target.value)} /></label>
    <div className="flex gap-2"><button ref={addPerson} className={button} disabled={busy} onClick={() => { setSelected(undefined); setEditing("person"); setMessage(""); setConflict(false); }}>Add person</button><button ref={addCompany} className={button} disabled={busy} onClick={() => { setSelected(undefined); setEditing("company"); setMessage(""); setConflict(false); }}>Add company</button></div>
    <p role="status" aria-live="polite">{message}</p>
    {conflict && <button className={button} disabled={busy} onClick={() => { reload(); setMessage("Latest contacts requested. Your draft is still open."); }}>Refresh contacts</button>}
    {deleting && <div role="alertdialog" aria-label="Delete contact?" className="space-y-3 rounded border p-4"><p>Delete {deleting.name}? Notes will be removed. People linked to this company will keep their details without a company link. This cannot be undone.</p><button autoFocus className={button} disabled={busy} onClick={() => { setDeleting(undefined); editButton.current?.focus(); }}>Keep contact</button>{" "}<button className={button} disabled={busy || draft?.id === deleting.id} onClick={async () => {
      if (await save({ action: "delete", id: deleting.id, revision: deleting.revision }, "Contact deleted.")) {
        setDeleting(undefined); setSelected(undefined); setEditing(undefined); addPerson.current?.focus();
      }
    }}>Confirm delete</button></div>}
    <div className="grid gap-6 md:grid-cols-2">
      <section aria-label="Contacts" className="rounded border p-4">
        <h2 className="font-serif text-xl">People and companies</h2>
        <ul className="divide-y">{matches.map(c => <li key={c.id} className="py-3"><button disabled={busy} className="text-left underline" onClick={() => { setSelected(c.id); setEditing(undefined); setMessage(""); setConflict(false); }}>{c.name}</button><p className="text-sm text-muted-foreground">{c.kind === "person" ? "Person" : "Company"}{c.companyId && ` · ${companies.get(c.companyId) ?? ""}`}</p></li>)}</ul>
        {!data?.contacts.length && <p>No contacts yet. Add your first person or company.</p>}
        {!!data?.contacts.length && !matches.length && <p>No matching contacts.</p>}
      </section>
      <section aria-label="Contact details" className="space-y-4 rounded border p-4">
        {editing && <form aria-label="Contact" key={draft ? `${draft.id}-${draft.revision}` : kind} onSubmit={submit} className="space-y-3">
          <h2 className="font-serif text-xl">{draft ? "Edit contact" : kind === "person" ? "New person" : "New company"}</h2>
          <label className="block">Name<input autoFocus name="name" className={field} required maxLength={200} defaultValue={draft?.name} /></label>
          <label className="block">Email<input name="email" type="email" className={field} maxLength={254} defaultValue={draft?.email} /></label>
          {kind === "person" && <label className="block">Company<select name="companyId" className={field} defaultValue={draft?.companyId ?? ""}><option value="">No company</option>{[...companies].map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></label>}
          <button className={button} disabled={busy}>Save contact</button>{" "}<button type="button" className={button} disabled={busy} onClick={closeEditor}>Cancel</button>
          {conflict && draft && <button type="button" className={button} disabled={busy} onClick={async () => {
            try {
              const latest = await api<ContactsData>("/api/pramaan/contacts");
              const fresh = latest.contacts.find(c => c.id === draft.id);
              if (!fresh) { setMessage("This contact is no longer available."); return; }
              setEditing(fresh); setConflict(false); reload(); setMessage("Latest contact loaded. Please enter your changes again.");
            } catch (e) { setMessage(e instanceof Error ? e.message : "Something went wrong. Please try again."); }
          }}>Replace draft with latest contact</button>}
        </form>}
        {contact ? <ContactDetail key={contact.id} contact={contact} company={companies.get(contact.companyId)} busy={busy} editing={draft?.id === contact.id} editButton={editButton} edit={() => { setDeleting(undefined); setEditing({ ...contact }); setMessage(""); setConflict(false); }} remove={() => setDeleting({ ...contact })} save={save} /> : !editing && <p>Choose a contact to see notes and history.</p>}
      </section>
    </div>
  </div>;
}

function ContactDetail({ contact, company, busy, editing, editButton, edit, remove, save }: { contact: Contact; company?: string; busy: boolean; editing: boolean; editButton: React.RefObject<HTMLButtonElement | null>; edit: () => void; remove: () => void; save: (body: Record<string, unknown>, success?: string) => Promise<boolean> }) {
  const [note, setNote] = useState("");
  const [deletingNote, setDeletingNote] = useState<{ index: number; revision: number }>();
  useEffect(() => { if (editing) setDeletingNote(undefined); }, [editing]);
  return <div className="space-y-4">
    {!editing && <><h2 className="font-serif text-xl">{contact.name}</h2><p>{contact.email}</p>{company && <p>Company: {company}</p>}
      <button ref={editButton} className={button} disabled={busy} onClick={edit}>Edit contact</button></>}
    <button className={button} disabled={busy || editing} onClick={remove}>Delete contact</button>
    <h3 className="font-serif text-lg">Notes</h3>
    {editing && <p>Save or cancel this edit before adding or deleting notes.</p>}
    <form onSubmit={async event => { event.preventDefault(); if (busy || editing) return; if (await save({ action: "note", id: contact.id, revision: contact.revision, note })) setNote(""); }} className="space-y-2">
      <label className="block">New note<textarea disabled={busy || editing} className={field} required maxLength={4000} value={note} onChange={e => setNote(e.target.value)} /></label><button className={button} disabled={busy || editing}>Add note</button>
    </form>
    {deletingNote && <div role="alertdialog" aria-label="Delete note?" className="space-y-2 rounded border p-3"><p>Delete this note? This cannot be undone.</p><button autoFocus className={button} disabled={busy || editing} onClick={() => setDeletingNote(undefined)}>Keep note</button>{" "}<button className={button} disabled={busy || editing} onClick={async () => { if (await save({ action: "delete-note", id: contact.id, revision: deletingNote.revision, noteIndex: deletingNote.index }, "Note deleted.")) setDeletingNote(undefined); }}>Confirm delete</button></div>}
    {!contact.notes.length && <p>No notes yet.</p>}
    <ul aria-label="Notes">{contact.notes.map((n, i) => <li key={i} className="border-b py-2"><p className="whitespace-pre-wrap">{n.text}</p><time className="text-sm text-muted-foreground" dateTime={n.at}>{new Date(n.at).toLocaleString()}</time>{" "}<button className={button} disabled={busy || editing} onClick={() => setDeletingNote({ index: i, revision: contact.revision })}>Delete note {i + 1}</button></li>)}</ul>
    <h3 className="font-serif text-lg">History</h3><ol aria-label="History">{contact.history.map((h, i) => <li key={i} className="border-l pl-3 pb-3">{h.text} <time className="block text-sm text-muted-foreground" dateTime={h.at}>{new Date(h.at).toLocaleString()}</time></li>)}</ol>
  </div>;
}

import "server-only";
import { randomUUID } from "node:crypto";
import { changeData, readData, text, checkRevision, CrmProblem } from "@/lib/pramaan/crm-data";
export type Contact = { id: string; revision: number; kind: "person" | "company"; name: string; email: string; companyId: string; notes: { text: string; at: string }[]; history: { text: string; at: string }[] };
export type ContactsData = { contacts: Contact[] };
const initial: ContactsData = { contacts: [] };
export async function getContacts(scope: string) {
  const state = await readData("contacts", scope, initial);
  return { contacts: state.contacts.map(contact => ({ ...contact, revision: contact.revision ?? 0 })) };
}
function recordHistory(contact: Contact, message: string, at: string) {
  contact.history.unshift({ text: message, at });
  contact.history.length = Math.min(contact.history.length, 50);
  contact.revision = (contact.revision ?? 0) + 1;
}
export function updateContacts(scope: string, body: Record<string, unknown>) {
  return changeData("contacts", scope, initial, state => {
    const at = new Date().toISOString();
    const existing = state.contacts.find(c => c.id === body.id);
    if (body.id && !existing) throw new CrmProblem("This contact is no longer available.", 404);
    if (existing) {
      existing.revision ??= 0;
      checkRevision(existing, body.revision, "contact");
    }
    if (body.action === "delete") {
      if (!existing) throw new CrmProblem("Choose a contact to remove.");
      state.contacts = state.contacts.filter(c => c.id !== existing.id);
      for (const person of state.contacts) {
        if (person.companyId === existing.id) {
          person.companyId = "";
          recordHistory(person, "Company link removed", at);
        }
      }
      return;
    }
    if (body.action === "note" || body.action === "delete-note") {
      if (!existing) throw new CrmProblem("Choose a contact for this note.");
      if (body.action === "note") {
        if (existing.notes.length >= 200) throw new CrmProblem("This contact has 200 notes. Remove a note to add another.");
        existing.notes.unshift({ text: text(body.note, "a note", 4000), at });
        recordHistory(existing, "Note added", at);
      } else {
        if (!Number.isInteger(body.noteIndex) || (body.noteIndex as number) < 0 || (body.noteIndex as number) >= existing.notes.length) throw new CrmProblem("This note is no longer available.", 404);
        existing.notes.splice(body.noteIndex as number, 1);
        recordHistory(existing, "Note removed", at);
      }
      return;
    }
    if (body.action !== "save") throw new CrmProblem("Choose an action to continue.");
    if (body.kind !== "person" && body.kind !== "company") throw new CrmProblem("Choose person or company.");
    const name = text(body.name, "a name");
    const email = text(body.email ?? "", "an email address", 254, false);
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new CrmProblem("Enter a valid email address.");
    const companyId = text(body.companyId ?? "", "a company", 100, false);
    if (companyId && (body.kind !== "person" || !state.contacts.some(c => c.id === companyId && c.kind === "company"))) throw new CrmProblem("Choose a company from this workspace.");
    if (existing && existing.kind !== body.kind) throw new CrmProblem("Keep the same contact type.");
    const fields = { name, email, companyId, kind: body.kind } as const;
    if (existing) {
      const linked = existing.companyId !== companyId;
      Object.assign(existing, fields);
      recordHistory(existing, linked ? "Company link changed" : "Contact updated", at);
    } else {
      if (state.contacts.length >= 2000) throw new CrmProblem("This workspace is full. Remove some contacts to add more.");
      state.contacts.push({ ...fields, id: randomUUID(), revision: 0, notes: [], history: [{ text: "Contact added", at }] });
    }
  });
}

-- Apply once to the app database before serving this block.
CREATE TABLE IF NOT EXISTS crm_contacts (
  scope text PRIMARY KEY,
  data jsonb NOT NULL CHECK (jsonb_typeof(data) = 'object')
);

"use client";

import { useCallback, useEffect, useState } from "react";
import { plainProblem } from "./plain";

// Browser half of the shared Pramaan helpers: calls this app's own /api/pramaan routes, never
// Pramaan itself, so no key is needed here.

/** An error from this app's API, with the server's own message and next step. */
export class ApiError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly next?: string,
    readonly status?: number,
    /** Present on a low-balance refusal: where to add credit. */
    readonly topUp?: { message: string; links: { label: string; url: string }[]; balance_micro: number },
  ) {
    super(message);
  }
}

export async function api<T>(url: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(url, { cache: "no-store", ...init });
  } catch {
    throw new ApiError("Can't reach the server. Check your connection and try again.", "network");
  }
  const data = await res.json().catch(() => undefined);
  if (!res.ok) {
    const e = data?.error ?? {};
    const p = plainProblem(e.code ?? "internal", res.status, e.message ?? "", e.next);
    throw new ApiError(p.message, e.code ?? "internal", p.next, res.status, e.top_up);
  }
  return data as T;
}

/** Micro-USD as dollars to 2 decimals: 905219 -> "$0.91". */
export function formatMicro(micro: number): string {
  if (micro > 0 && micro < 5_000) return "under $0.01";
  return `$${(micro / 1_000_000).toFixed(2)}`;
}

/** A most-it-can-cost price as a phrase: "up to $0.12", "$0.01" for a tiny price, "free" for none. Never "up to under". */
export const upTo = (micro: number) => (micro === 0 ? "free" : micro < 5_000 ? formatMicro(micro) : `up to ${formatMicro(micro)}`);

/** The same for a sentence about cost: "at most $0.12", "less than $0.01", "nothing". */
export const atMost = (micro: number) => (micro === 0 ? "nothing" : micro < 5_000 ? "less than $0.01" : `at most ${formatMicro(micro)}`);

/** Tell every block on the page that Pramaan data changed (they reload). */
export const PRAMAAN_CHANGED = "pramaan:changed";
export const announceChange = () => window.dispatchEvent(new Event(PRAMAAN_CHANGED));

/** GETs a URL, optionally every `pollMs`, and again on `announceChange()`. */
export function useResource<T>(url: string | null, pollMs?: number) {
  const [state, setState] = useState<{ data?: T; error?: ApiError; loading: boolean }>({ loading: url !== null });
  const [tick, setTick] = useState(0);
  const reload = useCallback(() => setTick((t) => t + 1), []);

  useEffect(() => {
    if (!url) return;
    let live = true;
    const load = () =>
      api<T>(url).then(
        (data) => live && setState({ data, loading: false }),
        (error: ApiError) => live && setState((s) => ({ data: s.data, error, loading: false })),
      );
    void load();
    const timer = pollMs ? setInterval(load, pollMs) : undefined;
    window.addEventListener(PRAMAAN_CHANGED, load);
    return () => {
      live = false;
      clearInterval(timer);
      window.removeEventListener(PRAMAAN_CHANGED, load);
    };
  }, [url, pollMs, tick]);

  return { ...state, reload };
}

/**
 * The current time, refreshed every `everyMs`, so expiry shows without a reload. It is 0 until
 * the page mounts: reading the clock while rendering breaks prerendering.
 */
export function useNow(everyMs = 1_000): number {
  const [now, setNow] = useState(0);
  useEffect(() => {
    const tick = () => setNow(Date.now());
    tick();
    const timer = setInterval(tick, everyMs);
    return () => clearInterval(timer);
  }, [everyMs]);
  return now;
}

// Plain wording for every screen: names, labels, dates. No ids, no snake_case, no raw JSON reach a
// person through these helpers. Pure functions, safe in the browser and on the server.

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** "31 Oct, 8:03 PM" (and the year when it isn't this year). `time: false` gives "31 Oct". */
export function formatDate(value: string | number | Date | undefined, opts: { time?: boolean } = {}): string {
  if (value === undefined || value === "") return "";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return "";
  const year = d.getFullYear() === new Date().getFullYear() ? "" : ` ${d.getFullYear()}`;
  const day = `${d.getDate()} ${MONTHS[d.getMonth()]}${year}`;
  if (opts.time === false) return day;
  const h = d.getHours() % 12 || 12;
  return `${day}, ${h}:${String(d.getMinutes()).padStart(2, "0")} ${d.getHours() < 12 ? "AM" : "PM"}`;
}

/** A calendar day ("2026-10-30") as "30 Oct". */
export function formatDay(day: string, withYear = true): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(day);
  if (!m) return day;
  const year = !withYear || Number(m[1]) === new Date().getFullYear() ? "" : ` ${m[1]}`;
  return `${Number(m[3])} ${MONTHS[Number(m[2]) - 1]}${year}`;
}

/** Cents as money: 2000 and "usd" is "$20.00". */
export const formatCents = (cents: number, currency = "usd") => new Intl.NumberFormat("en", { style: "currency", currency }).format(cents / 100);

const cap = (s: string) => s.replace(/^./, (c) => c.toUpperCase());

/** "snake_case", "camelCase" and "kebab-case" as plain words: "Account name". */
export const humanize = (key: string) => cap(key.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/[_-]+/g, " ").trim().toLowerCase());

// Plain names for what ran. Others are built from the id's words, verb first.
const ACTIONS: Record<string, string> = {
  "email.send": "Send an email",
  "sms.send": "Send a text message",
  "social.post.publish": "Publish a social post",
  "payments.payout.create": "Send a payout",
  "voice.call.start": "Make a phone call",
  "apps.connection.delete": "Remove a connected account",
  "company.research": "Research a company",
  "broadcast.send": "Send a broadcast",
  "llm.complete": "Write with AI",
  "llm.chat": "Chat with AI",
  "web.read": "Read a web page",
  "web.search": "Search the web",
  "companies.news": "Find company news",
  "companies.registry.search": "Look up a company register",
  "outreach.contacts.list": "List contacts",
  "outreach.broadcast.create": "Create a broadcast",
  "outreach.broadcast.send": "Send a broadcast",
  "assessment.exam.build": "Build an exam",
  "assessment.exam.publish": "Publish an exam",
  "assessment.invitation.create": "Invite a candidate",
  "assessment.invitation.revoke": "Withdraw an invitation",
  "assessment.invite.send": "Invite candidates",
  "assessment.invites.clean-up": "Clean up unused invitations",
  "memory.forget": "Forget everything",
  "memory.item.delete": "Delete a memory",
  "messaging.opt-out.add": "Add an opt-out",
  "messaging.opt-out.remove": "Remove an opt-out",
};

const VERBS = new Set([
  "send", "create", "get", "list", "build", "research", "publish", "delete", "revoke", "start", "run", "check", "add",
  "remove", "search", "read", "write", "post", "call", "close", "update", "invite", "finish", "complete", "record",
  "upload", "download", "connect", "forget", "decide", "estimate", "cancel", "summarize",
]);

/** A capability or mission id as a plain action: "company.research" is "Research a company". */
export function actionName(id: string): string {
  if (ACTIONS[id]) return ACTIONS[id];
  const words = id.split(/[._-]+/).filter(Boolean);
  const last = words[words.length - 1];
  if (words.length > 1 && last && VERBS.has(last)) return cap([last, ...words.slice(0, -1)].join(" "));
  return cap(words.join(" "));
}

/** Who asked, in words a person uses. Never a member id. */
export function requesterLabel(r: { kind: string; act?: string; member_id?: string }): string {
  if (r.member_id) return "A team member";
  if (r.kind === "key") return "Your app";
  return r.act === "agent" ? "An AI assistant" : "An app";
}

// Plain names for common input keys; anything else comes from humanize().
const LABELS: Record<string, string> = {
  to: "To", cc: "Copy to", bcc: "Hidden copy to", from: "From", subject: "Subject", text: "Message", body: "Message",
  html: "Message", amount_micro: "Amount", phone: "Phone", url: "Link", q: "Search for", query: "Search for",
  accountId: "Account", prompt: "What to write", maxWords: "Longest answer (words)",

};

export const fieldLabel = (key: string) => LABELS[key] ?? humanize(key);

/** An internal id (`mbr_viewer`, `apr_x1`, `acc_mail1`): shown only behind a Copy reference control. */
/** A file size in plain units: "3.2 MB". */
export const formatBytes = (n: number) => (n < 1_000 ? `${n} B` : n < 1_000_000 ? `${(n / 1_000).toFixed(0)} KB` : n < 1_000_000_000 ? `${(n / 1_000_000).toFixed(1)} MB` : `${(n / 1_000_000_000).toFixed(1)} GB`);

export const looksLikeId = (v: unknown): v is string => typeof v === "string" && /^[a-z]{2,6}_[A-Za-z0-9_-]{3,}$/.test(v);

// Developer wording that must never reach a person: keys, headers, env vars, status codes, ids.
const DEV_WORDS = /api[ -]?key|authorization|\bheaders?\b|PRAMAAN_[A-Z_]+|idempotency|retry-after|request[_ ]id|\bHTTP \d{3}\b|\b(?:answered|status)(?: with)? \d{3}\b|support@|apps\.connection/i;
const SETUP = "Ask whoever runs this app to check its setup.";

/**
 * An error's message and next step as a person should read them. Local signed-out errors keep
 * their own words; anything that names a key, header, env var or status code is replaced.
 */
export function plainProblem(code: string, status: number | undefined, message: string, next?: string): { message: string; next?: string } {
  if (code === "signed_out") return { message: "Sign in to see this.", ...(next && !DEV_WORDS.test(next) ? { next } : {}) };
  if (code === "unauthorized") return { message: "This app can't reach its service right now.", next: SETUP };
  const fallback = status === 404 ? "We couldn't find that." : status && status >= 500 ? "Something went wrong on our side. Try again in a minute." : status ? "That didn't work. Try again." : "Something went wrong. Try again.";
  const clean = DEV_WORDS.test(message) || /^(?:the )?(?:api|server|pramaan) answered/i.test(message) ? fallback : message;
  const step = next === undefined ? undefined : DEV_WORDS.test(next) ? (code === "connection_required" ? SETUP : undefined) : next;
  return { message: clean, ...(step ? { next: step } : {}) };
}

const STATE_WORDS: Record<string, string> = {
  running: "Running", done: "Done", failed: "Failed", cancelled: "Cancelled", pending: "Waiting", waiting: "Waiting",
  waiting_for_approval: "Waiting for approval", approved: "Approved", denied: "Declined", expired: "Expired",
};

/** A status word as plain text: "waiting_for_approval" is "Waiting for approval". */
export const stateWord = (s: string) => STATE_WORDS[s] ?? humanize(s);

/**
 * Who is signed in, as a Pramaan member_id (from GET /v1/members). Replace this body with your own
 * auth: look up the signed-in user and return the member_id you mapped them to. Return undefined
 * for anyone else; they get a read-only view.
 */
export async function currentMemberId(request: Request): Promise<string | undefined> {
  // Demo and tests only: with the fake on, a cookie picks the member, `none` means signed out, and
  // no cookie means the owner demo member. Never trust a cookie for this in production; it would
  // let anyone claim to be an approver.
  if (process.env.PRAMAAN_FAKE === "1") {
    const who = readCookie(request, "pramaan_member");
    return who === "none" ? undefined : (who ?? "mbr_owner");
  }
  return undefined;
}

/**
 * Your own reference for the signed-in person, as the connections block sends it to Pramaan
 * (`endUserRef`: 1 to 128 letters, digits, `_`, `.` or `-`; never an email or name). Replace this
 * body with your user id. Return undefined when nobody is signed in.
 */
export async function currentEndUserRef(request: Request): Promise<string | undefined> {
  // Demo and tests only, like the member cookie above.
  if (process.env.PRAMAAN_FAKE === "1") {
    if (readCookie(request, "pramaan_member") === "none") return undefined;
    return readCookie(request, "pramaan_user") ?? "user-42";
  }
  return undefined;
}

function readCookie(request: Request, name: string): string | undefined {
  for (const part of (request.headers.get("cookie") ?? "").split(";")) {
    const [key, ...value] = part.trim().split("=");
    if (key === name) return decodeURIComponent(value.join("=")) || undefined;
  }
  return undefined;
}

/** Authorise writes using trusted membership data. Wire this alongside currentMemberId. */
export async function canWrite(member: string, scope: string): Promise<boolean> {
  if (process.env.PRAMAAN_FAKE === "1") return member === "mbr_owner" && scope === member;
  // Deny until the host app checks this member's write role in the chosen workspace.
  return false;
}

import "server-only";
import postgres from "postgres";
import { canWrite, currentMemberId } from "@/lib/pramaan/session";

export class CrmProblem extends Error {
  constructor(message: string, readonly status = 400) { super(message); }
}

// Replace with an authorised workspace lookup to share records across a team.
export async function crmScope(request: Request) {
  const member = await currentMemberId(request);
  if (!member) throw new CrmProblem("Sign in to see this.", 401);
  const scope = member;
  if (request.method !== "GET") {
    const origin = request.headers.get("origin");
    // Use the configured public origin when the app sits behind a rewriting proxy.
    const appOrigin = new URL(process.env.CRM_APP_URL || request.url).origin;
    if (origin && origin !== appOrigin) throw new CrmProblem("Please reload the page and try again.", 403);
    if (!await canWrite(member, scope)) throw new CrmProblem("You don't have permission to change this workspace.", 403);
  }
  return scope;
}

const memory = new Map<string, unknown>();
let sql: ReturnType<typeof postgres> | undefined;
export function crmDatabase() {
  if (!process.env.DATABASE_URL) throw new CrmProblem("Your workspace is not connected yet.", 503);
  return sql ??= postgres(process.env.DATABASE_URL, { max: 5, prepare: false });
}
export async function closeCrmDatabase() {
  await sql?.end();
  sql = undefined;
}
export function resetCrmFake() { memory.clear(); }
/** In-memory rows standing in for one table while the fake is on. */
export function fakeRows<T>(table: string): T[] {
  let rows = memory.get(`rows:${table}`) as T[] | undefined;
  if (!rows) memory.set(`rows:${table}`, rows = []);
  return rows;
}
type Block = "contacts" | "pipeline";
function table(block: Block) {
  if (block !== "contacts" && block !== "pipeline") throw new CrmProblem("Choose a workspace list.");
  return `crm_${block}`;
}
const jsonCopy = <T,>(value: T): T => JSON.parse(JSON.stringify(value));
const MAX_DOCUMENT_BYTES = 4 * 1024 * 1024;
function documentJson(value: unknown) {
  const json = JSON.stringify(value);
  if (Buffer.byteLength(json, "utf8") > MAX_DOCUMENT_BYTES) throw new CrmProblem("This workspace is full. Remove some entries before saving more.");
  return json;
}

export async function readData<T>(block: Block, scope: string, initial: T): Promise<T> {
  const name = table(block);
  if (process.env.PRAMAAN_FAKE === "1") return jsonCopy((memory.get(`${block}:${scope}`) ?? initial) as T);
  const rows = await crmDatabase().unsafe(`select data from ${name} where scope = $1`, [scope]);
  return rows[0]?.data ?? jsonCopy(initial);
}
export async function changeData<T>(block: Block, scope: string, initial: T, change: (state: T) => void): Promise<T> {
  const name = table(block);
  if (process.env.PRAMAAN_FAKE === "1") {
    const key = `${block}:${scope}`;
    const state = jsonCopy((memory.get(key) ?? initial) as T);
    change(state);
    const stored = JSON.parse(documentJson(state)) as T;
    memory.set(key, stored);
    return jsonCopy(stored);
  }
  return await crmDatabase().begin(async tx => {
    // Bind serialized JSON as text so the driver does not encode the string a second time.
    await tx.unsafe(`insert into ${name} (scope, data) values ($1, $2::text::jsonb) on conflict (scope) do nothing`, [scope, documentJson(initial)]);
    const rows = await tx.unsafe(`select data from ${name} where scope = $1 for update`, [scope]);
    const state = rows[0].data as T;
    change(state);
    const json = documentJson(state);
    await tx.unsafe(`update ${name} set data = $2::text::jsonb where scope = $1`, [scope, json]);
    return JSON.parse(json) as T;
  }) as T;
}

export function checkRevision(record: { revision: number }, expected: unknown, noun: "contact" | "card") {
  if (!Number.isSafeInteger(expected) || expected !== record.revision) throw new CrmProblem(`This ${noun} changed since you opened it. Reload to see the latest.`, 409);
}
export function text(value: unknown, label: string, max = 200, required = true): string {
  if (typeof value !== "string" || (required && !value.trim())) throw new CrmProblem(`Enter ${label}.`);
  if (value.trim().length > max) throw new CrmProblem(`Use ${label} of up to ${max} characters.`);
  return value.trim();
}

const MAX_BODY_BYTES = 20_000;
const shorterEntry = () => new CrmProblem("Please use a shorter entry.");
export async function readBody(request: Request): Promise<Record<string, unknown>> {
  if (request.headers.get("content-type")?.split(";")[0].trim().toLowerCase() !== "application/json") throw new CrmProblem("Please check the form and try again.", 415);
  const declared = request.headers.get("content-length");
  if (declared !== null) {
    if (!/^\d+$/.test(declared)) throw new CrmProblem("Please check the form and try again.");
    if (Number(declared) > MAX_BODY_BYTES) throw shorterEntry();
  }
  const reader = request.body?.getReader();
  if (!reader) throw new CrmProblem("Please check the form and try again.");
  let size = 0;
  let raw = "";
  const decoder = new TextDecoder();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_BODY_BYTES) {
        await reader.cancel().catch(() => undefined);
        throw shorterEntry();
      }
      raw += decoder.decode(value, { stream: true });
    }
    raw += decoder.decode();
  } finally { reader.releaseLock(); }
  let body: unknown;
  try { body = JSON.parse(raw); } catch { throw new CrmProblem("Please check the form and try again."); }
  if (!body || typeof body !== "object" || Array.isArray(body)) throw new CrmProblem("Please check the form and try again.");
  return body as Record<string, unknown>;
}
export async function crmRoute(request: Request, run: (scope: string, body: Record<string, unknown>) => Promise<unknown>) {
  try {
    const scope = await crmScope(request);
    const body = request.method === "GET" ? {} : await readBody(request);
    return Response.json(await run(scope, body), { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return Response.json({ error: { message: error instanceof CrmProblem ? error.message : "Something went wrong. Please try again." } }, { status: error instanceof CrmProblem ? error.status : 500, headers: { "Cache-Control": "no-store" } });
  }
}
